package com.tekwatt.ocpp.service;import com.tekwatt.ocpp.entity.OcppMessage;import com.tekwatt.ocpp.repository.OcppMessageRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class OcppAuditService{private final OcppMessageRepository repo;public OcppAuditService(OcppMessageRepository r){repo=r;}@Transactional public void record(String station,String direction,int type,String unique,String action,String payload){repo.save(new OcppMessage(station,direction,type,unique,action,payload));}}
